-- Canonical public places are separate from private, user-scoped selection history.
CREATE TABLE tc_destinations (
 id uuid PRIMARY KEY,
 name text NOT NULL,
 kind text NOT NULL CHECK (kind IN ('country','region','city','place')),
 country_code text NOT NULL DEFAULT '',
 country_name text NOT NULL DEFAULT '',
 parent_id uuid REFERENCES tc_destinations(id) ON DELETE RESTRICT,
 formatted_address text NOT NULL DEFAULT '',
 latitude double precision,
 longitude double precision,
 time_zone text NOT NULL DEFAULT '',
 aliases jsonb NOT NULL DEFAULT '[]'::jsonb,
 metadata jsonb NOT NULL DEFAULT '{}'::jsonb,
 theme jsonb NOT NULL DEFAULT '{}'::jsonb,
 provider text NOT NULL,
 provider_id text NOT NULL,
 created_at timestamptz NOT NULL DEFAULT now(),
 updated_at timestamptz NOT NULL DEFAULT now(),
 UNIQUE(provider, provider_id),
 CHECK ((latitude IS NULL) = (longitude IS NULL)),
 CHECK (latitude BETWEEN -90 AND 90),
 CHECK (longitude BETWEEN -180 AND 180)
);
CREATE INDEX tc_destinations_country ON tc_destinations(country_code, kind);
CREATE TABLE tc_destination_terms (
 destination_id uuid NOT NULL REFERENCES tc_destinations(id) ON DELETE CASCADE,
 term text NOT NULL,
 PRIMARY KEY(destination_id, term)
);
CREATE INDEX tc_destination_terms_prefix ON tc_destination_terms(term text_pattern_ops, destination_id);
CREATE TABLE tc_destination_usage (
 user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
 stop_id uuid NOT NULL REFERENCES tc_stops(id) ON DELETE CASCADE,
 destination_id uuid NOT NULL REFERENCES tc_destinations(id) ON DELETE CASCADE,
 last_selected_at timestamptz NOT NULL DEFAULT now(),
 PRIMARY KEY(user_id, stop_id, destination_id)
);
CREATE INDEX tc_destination_usage_rank ON tc_destination_usage(user_id, destination_id, last_selected_at DESC);
CREATE INDEX tc_destination_usage_recent ON tc_destination_usage(user_id, last_selected_at DESC);

-- 249 ISO 3166 countries/territories from IANA tzdata iso3166.tab (public domain,
-- Paul Eggert, 2025-07-01 revision). IDs are UUIDv5 of the documented ISO key.
-- A country time zone is supplied only where it is unambiguous.
SELECT id, lower(name) FROM tc_destinations
UNION SELECT id, lower(alias) FROM tc_destinations, jsonb_array_elements_text(aliases) AS alias
ON CONFLICT DO NOTHING;
